#!/usr/bin/env python3
"""The Docker board: a switch per container (starts or stops it) and what Docker is holding, as MenuSprite blocks."""
import json
import shlex
import subprocess

SHOWN = 12


def docker(*args):
    return subprocess.run(["docker", *args], capture_output=True, text=True, timeout=20)


def plain(text):
    # Board text reads {word} as one of the sprite's values; a container name never means one.
    return text.replace("{", "{\u200b")


listed = docker("ps", "-a", "--format", "{{.Names}}\t{{.Image}}\t{{.State}}\t{{.Status}}\t{{.Ports}}")
if listed.returncode != 0:
    reason = (listed.stderr.strip().splitlines() or ["docker ps failed"])[-1]
    print(json.dumps([
        {"text": "Docker is not running", "font": "headline", "icon": "exclamationmark.triangle"},
        {"text": plain(reason[:200]), "font": "caption", "color": "gray"},
    ]))
    raise SystemExit(0)

containers = []
for line in listed.stdout.splitlines():
    name, image, state, status, ports = (line.split("\t") + [""] * 5)[:5]
    containers.append({"name": name, "image": image, "running": state == "running", "status": status, "ports": ports})
containers.sort(key=lambda c: (not c["running"], c["name"]))
running = sum(c["running"] for c in containers)
images = len(set(docker("images", "-q").stdout.split()))


def row(c):
    port = c["ports"].split(",")[0].split("->")[0].rsplit(":", 1)[-1] if c["running"] and c["ports"] else ""
    detail = " · ".join(part for part in (c["image"], c["status"], "port " + port if port else "") if part)
    return {"row": [
        {"stack": [
            {"text": plain(c["name"]), "lines": 1, "truncate": "middle"},
            {"text": plain(detail), "font": "caption", "color": "gray", "lines": 1},
        ], "spacing": 1},
        {"toggle": "", "value": c["running"], "color": "green", "fit": True,
         "on": "docker start " + shlex.quote(c["name"]), "off": "docker stop " + shlex.quote(c["name"])},
    ]}


rows = [row(c) for c in containers[:SHOWN]]
if len(containers) > SHOWN:
    rows.append({"text": "and %d more in Docker Desktop" % (len(containers) - SHOWN), "font": "caption", "color": "gray"})
print(json.dumps([
    {"row": [{"value": running, "caption": "Running"},
             {"value": len(containers) - running, "caption": "Stopped"},
             {"value": images, "caption": "Images"}]},
    {"card": rows or [{"text": "No containers yet.", "font": "caption", "color": "gray"}], "title": "Containers"},
]))
